const input = $input.first().json;
const payload = input.body || input;
const message = payload.message || {};
const customer = payload.customer || {};
const company = payload.company || {
  id: '6d558f61-4f94-40aa-b96c-b8d6e8c38523',
  name: 'Pizzaria Big Burguer',
  segment: 'restaurant'
};
const userText = String(message.content || message.text || payload.content || '').trim() || 'Cliente iniciou atendimento.';
const system = [
  'Voce e a assistente virtual da Pizzaria Big Burguer.',
  'Responda em portugues brasileiro, com tom simpatico e direto.',
  'Atendimento por WhatsApp: mensagens curtas, sem texto longo.',
  'Nunca invente preco, produto, taxa, prazo ou disponibilidade.',
  'Se o cliente quiser pedir algo, colete uma informacao por vez e confirme antes de finalizar.',
  'Se faltar cardapio/contexto, explique que ainda esta em modo teste e peca para um atendente confirmar.'
].join('\n');

return [{
  json: {
    payload,
    company,
    customer,
    inbound: userText,
    openaiBody: {
      model: 'gpt-4.1-mini',
      temperature: 0.2,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: `Cliente: ${customer.name || 'Cliente'}\nMensagem: ${userText}` }
      ]
    }
  }
}];

const ai = $input.first().json;
const text = ai.choices?.[0]?.message?.content?.trim() || 'Oi! Ja te respondo por aqui.';
return [{
  json: {
    ok: true,
    mode: 'teste_ia',
    ai: {
      provider: 'openai',
      model: ai.model || 'gpt-4.1-mini',
      text
    },
    next: {
      sendToCustomer: false,
      note: 'MVP: resposta gerada. Proximo passo e plugar envio de volta ao Ticketz/SaaS.'
    }
  }
}];
